def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.75
        return max(0, min(budget, base))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    highest_prev = max(prev_bids) if prev_bids else 0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if urgency >= 5:
        bid = DAILY_SALARY * 0.96
    elif urgency >= 3:
        bid = DAILY_SALARY * 0.82
    elif scarcity == 2:
        bid = DAILY_SALARY * 0.62
    elif scarcity == 1:
        bid = DAILY_SALARY * 0.50
    else:
        bid = DAILY_SALARY * 0.34

    if highest_prev > 0:
        if scarcity >= 1 or urgency >= 2:
            target = highest_prev + 1.5
            if target > bid:
                bid = target
        elif highest_prev >= DAILY_SALARY * 0.85:
            bid = min(bid, DAILY_SALARY * 0.38)

    if desperate_count >= 2 and scarcity >= 1:
        bid = max(bid, DAILY_SALARY * 0.72)
    if rich_count >= 2 and scarcity == 2:
        bid = max(bid, DAILY_SALARY * 0.78)

    if day >= 8 and (hp <= 4 or no_water >= 1):
        bid = max(bid, DAILY_SALARY * 0.88)

    bid = max(0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # Fallback if no opponents
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.45)

    # Read yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Determine aggressiveness threshold
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Budget/health based urgency
    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Target bid logic
    # If opponents were bidding very high yesterday, contest more but cap by budget.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If we're weak or have been without water, be more aggressive.
        if hp <= 2.5 or no_water_days >= 2:
            raw_bid = max(highest_prev_bid, second_prev_bid) + 1.0
            # Ensure we don't exceed our ability
            raw_bid = min(raw_bid, budget, DAILY_SALARY * 0.95)
            return max(0.0, raw_bid)
        else:
            # Outbid slightly above the next best to secure water.
            raw_bid = second_prev_bid + 1.0
            raw_bid = min(raw_bid, budget, DAILY_SALARY * 0.75)
            return max(0.0, raw_bid)

    # If bids were moderate/low, bid enough to stay competitive but avoid overpay.
    # Use supply pressure: lower supply -> higher bid.
    supply_pressure = 1.0
    if supply <= float(MIN_SUPPLY):
        supply_pressure = 1.0
    elif supply >= float(MAX_SUPPLY):
        supply_pressure = 0.6
    else:
        # linear scale between 15..25
        supply_pressure = 1.0 - (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY)) * 0.4

    base_bid = DAILY_SALARY * (0.42 * supply_pressure)

    # If we have been without water, increase bid
    if no_water_days >= 1:
        base_bid *= 1.25
    if hp <= 3.0:
        base_bid *= 1.35

    # If we have a signal from yesterday highest bid, nudge above it slightly when close.
    # (Still keep under budget.)
    if highest_prev_bid > 0.0:
        # If they were bidding close to our base, we should beat them.
        if highest_prev_bid >= base_bid * 0.9:
            base_bid = highest_prev_bid + 1.0

    bid = min(budget, base_bid)
    return max(0.0, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    total_water_needed_by_opponents = sum([o['water_requirement'] for o in alive_opponents])
    total_water_demand = WATER_REQ + total_water_needed_by_opponents

    yesterday_bids = []
    for opp_data in alive_opponents:
        prev_trace = opp_data.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0

    # --- Bidding Strategy ---

    # 1. Critical HP: Prioritize survival
    if my_hp <= 2:
        return min(my_budget, DAILY_SALARY * 0.95)

    # 2. Low HP: Still high priority
    if my_hp <= 4:
        # If supply is very tight (e.g., less than total demand + a buffer)
        if current_supply < total_water_demand + 5:
            return min(my_budget, DAILY_SALARY * 0.8)
        else:
            return min(my_budget, DAILY_SALARY * 0.7)

    # 3. Normal HP strategy
    base_bid = DAILY_SALARY * 0.4 # Default moderate bid

    # Adjust based on supply scarcity and competition
    if current_supply < total_water_demand + 5: # Supply is tight
        if highest_prev_bid > DAILY_SALARY * 0.5:
            base_bid = min(DAILY_SALARY * 0.7, highest_prev_bid + 5)
        else:
            base_bid = DAILY_SALARY * 0.55
    else: # Supply is relatively abundant
        if highest_prev_bid < DAILY_SALARY * 0.4:
            base_bid = max(DAILY_SALARY * 0.25, highest_prev_bid + 1)
        else:
            base_bid = DAILY_SALARY * 0.4
            if my_hp >= 8: # If HP is very good, be more conservative
                base_bid *= 0.85

    # Ensure bid doesn't exceed budget and meets a minimum competitive threshold
    final_bid = min(my_budget, max(base_bid, 15.0))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    # Check yesterday's trace for pattern
    yesterday_max = None
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if yesterday_max is None or prev['bid'] > yesterday_max:
                yesterday_max = prev['bid']
    if yesterday_max is not None:
        # We have history: respond to highest previous bid
        if my_status['hp'] <= 3:
            target = min(my_status['budget'], max(DAILY_SALARY * 0.8, yesterday_max + 1))
        else:
            target = min(my_status['budget'], max(DAILY_SALARY * 0.5, yesterday_max + 0.5))
        return target
    else:
        # No history (first day or all opponents have no trace)
        if my_status['hp'] <= 3:
            return min(my_status['budget'], DAILY_SALARY * 0.75)
        elif my_status['hp'] <= 5:
            return min(my_status['budget'], DAILY_SALARY * 0.55)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.35)
